from packaging.dependency_groups import resolve_dependency_groups as _resolve_dependency_groups
from typing import List, Dict, Any, Union


def resolve_dependency_groups(dependency_groups: Dict[str, List[Union[str, Dict[str, str]]]], groups: List[str]) -> List[str]:
    """Resolve a dependency group to a tuple of requirements, as strings. dependency_groups: the parsed contents of the [dependency-groups] table from pyproject.toml. groups: the name of the group(s) to resolve. Example: resolve_dependency_groups({"group1": ["requests"]}, ["group1"]) -> ["requests"]."""
