from typing import Any, Mapping, Dict, Union
from packaging.pylock import Pylock, PylockValidationError


def create_pylock_from_dict(data: Dict[str, Any]) -> Dict[str, Any]:
    """Create and validate a Pylock instance from a TOML dictionary.

    Args:
        data: A dictionary representing pylock data

    Returns:
        A dictionary representation of the validated Pylock instance

    Example:
        >>> create_pylock_from_dict({"package": "requests", "version": "2.28.1"})
        {'package': 'requests', 'version': '2.28.1'}
    """
    try:
        pylock_instance = Pylock.from_dict(data)
        # Convert to dictionary representation
        return {
            "package": pylock_instance.package,
            "version": pylock_instance.version
        }
    except PylockValidationError as e:
        raise ValueError(f"Invalid pylock data: {str(e)}")
    except Exception as e:
        raise ValueError(f"Error creating pylock: {str(e)}")

